// ─────────────────────────────────────────────────────────────────────────────
// Download format menu (one ⬇ Download button → choose JSON or CSV)
// ─────────────────────────────────────────────────────────────────────────────
// ── App menu (☰) ────────────────────────────────────────────────────────────
// Replaces the old header button row. Same open/close contract as the download menu it
// supersedes: stop the opening click, then keep it open until an actual menu action is
// clicked or the user clicks outside the menu.
let _appMenuDocListenerOn = false;

function onAppMenuDocClick(e){
  const m=document.getElementById('appMenu');
  const btn=document.getElementById('appMenuBtn');
  const t=e&&e.target;
  if(!m || m.hasAttribute('hidden')){ closeAppMenu(); return; }
  if(btn && t && (t===btn || (btn.contains && btn.contains(t)))) return;
  if(t && m.contains && m.contains(t)){
    const action=(t.closest && t.closest('button.hdr-menu-item, .hdr-menu-item button, [data-menu-close="1"]')) || null;
    if(action && m.contains(action)) closeAppMenu();
    return;
  }
  closeAppMenu();
}

function toggleAppMenu(e){
  if(e) e.stopPropagation();
  const m=document.getElementById('appMenu'); if(!m) return;
  const btn=document.getElementById('appMenuBtn');
  if(m.hasAttribute('hidden')){
    m.removeAttribute('hidden');
    if(btn){ btn.classList.add('open'); btn.setAttribute('aria-expanded','true'); }
    if(!_appMenuDocListenerOn){
      document.addEventListener('click', onAppMenuDocClick);
      _appMenuDocListenerOn = true;
    }
  } else {
    closeAppMenu();
  }
}
function closeAppMenu(){
  const m=document.getElementById('appMenu'); if(m) m.setAttribute('hidden','');
  const btn=document.getElementById('appMenuBtn');
  if(btn){ btn.classList.remove('open'); btn.setAttribute('aria-expanded','false'); }
  if(_appMenuDocListenerOn){
    document.removeEventListener('click', onAppMenuDocClick);
    _appMenuDocListenerOn = false;
  }
}
// The app has two top-level VIEWS: Projections (the builder — season tabs, team sidebar) and
// the League Analyzer (snapshot-driven, season-agnostic). This returns to the former.
// Where the user was in the projections builder before they opened the League Analyzer, so
// returning puts them back rather than dumping them on Passing. Stores the phase, the team and
// the scroll offset — being returned to the right tab but the top of a long page is still a
// loss of place.
let _preLeagueView = null;
function rememberProjectionsView(){
  if(currentPhase==='League') return;   // already in the analyzer; don't overwrite the stash
  _preLeagueView = {
    phase: currentPhase,
    team: currentTeam,
    scope: (typeof rankScope!=='undefined' ? rankScope : null),
    y: window.scrollY || document.documentElement.scrollTop || 0,
  };
}
function showProjectionsView(){
  if(currentPhase==='League'){
    const v=_preLeagueView;
    // Restore the remembered spot. The stash always wins on the team too — requiring
    // currentTeam to still match silently discarded a valid stash whenever something
    // inside the analyzer touched the team, and the fallback then dumped users on the
    // full rankings ("← Projections" must mean the builder, not the rankings page).
    if(v && v.phase && v.phase!=='League'){
      if(v.team) currentTeam = v.team;
      currentPhase = v.phase;
      if(v.scope && typeof rankScope!=='undefined') rankScope = v.scope;
    } else {
      // No stash (a reload wiped the in-memory snapshot): land on a team's builder page,
      // never the rankings dump.
      if(!currentTeam && typeof TEAMS!=='undefined' && TEAMS && TEAMS.length){
        currentTeam = TEAMS[0];
        if(typeof ensureTeam==='function'){ try{ ensureTeam(currentTeam); }catch(e){} }
      }
      currentPhase = currentTeam ? 'Passing' : 'Rankings';
    }
    renderContent();
    syncAppChrome();
    // Restore scroll after layout, clamped to the rebuilt page height.
    if(_preLeagueView && _preLeagueView.y){
      const y=_preLeagueView.y;
      requestAnimationFrame(()=>{
        const max=Math.max(0, document.documentElement.scrollHeight - window.innerHeight);
        window.scrollTo(0, Math.min(y, max));
      });
    }
    return;
  }
  // From global views (Rankings / league-wide Advanced), jump back into the
  // projection builder phases instead of re-rendering the same global view.
  if(currentPhase==='Rankings' || currentPhase==='AdvancedLeague'){
    const stashed = _preLeagueView && _preLeagueView.phase;
    const usableStash = stashed && !['League','Rankings','AdvancedLeague'].includes(stashed);
    currentPhase = usableStash ? stashed : 'Passing';
  }
  renderContent();
  syncAppChrome();
}
// Show/hide chrome that only belongs to one view. The season tabs do nothing in the League
// Analyzer (a snapshot isn't a season), so they'd just be dead controls taking a row of
// screen — hide them there. Also keeps the menu's view items in sync.
function syncAppChrome(){
  const setCls = (el, cls, on)=>{
    if(!el || !el.classList) return;
    if(el.classList.toggle) el.classList.toggle(cls, !!on);
    else if(on) el.classList.add(cls);
    else el.classList.remove(cls);
  };
  const setHidden = (el, hidden)=>{
    if(!el) return;
    if(hidden){
      if(typeof el.setAttribute==='function') el.setAttribute('hidden','');
      else el.hidden = true;
    } else {
      if(typeof el.removeAttribute==='function') el.removeAttribute('hidden');
      else el.hidden = false;
    }
  };
  const phase = String((typeof currentPhase!=='undefined' && currentPhase) || '');
  const inLeague = (phase==='League' || phase==='AdvancedLeague');
  const inRankings = phase==='Rankings';
  const inProjections = !inLeague && !inRankings;
  const viewLabel = inProjections ? 'Projections' : (inRankings ? 'Rankings' : 'Leagues');
  // Season tabs AND the NFL team sidebar are both projection-builder chrome: a snapshot
  // isn't a season, and picking the Lions does nothing to your dynasty league. Hiding both
  // in the analyzer removes two dead controls and ~75px of vertical space on a phone.
  const bar=document.getElementById('seasonBar');
  setCls(bar, 'hidden-view', inLeague);
  const side=document.getElementById('sidebar');
  setCls(side, 'hidden-view', inLeague);
  const mp=document.getElementById('menuProjView');
  const mr=document.getElementById('menuRankView');
  const ml=document.getElementById('menuLeagueView');
  setCls(mp, 'active', inProjections);
  setCls(mr, 'active', inRankings);
  setCls(ml, 'active', inLeague);

  document.querySelectorAll('.menu-view-proj').forEach(el=>{
    setHidden(el, !inProjections);
  });
  document.querySelectorAll('.menu-view-rank').forEach(el=>{
    setHidden(el, !inRankings);
  });
  document.querySelectorAll('.menu-view-league').forEach(el=>{
    setHidden(el, !inLeague);
  });

  const viewSpecificSec = document.getElementById('menuViewSpecificSec');
  if(viewSpecificSec) viewSpecificSec.textContent = viewLabel;

  // "Switch Analyst" appears in any view when imported projections have multiple analysts.
  const menuSA = document.getElementById('menuSwitchAnalyst');
  if(menuSA) setHidden(menuSA, !(importedAnalystData && Object.keys(importedAnalystData).length > 1));

  if(typeof refreshLeagueSyncBtn==='function') refreshLeagueSyncBtn();
  if(typeof syncAuthChrome==='function') syncAuthChrome();
}

// ─────────────────────────────────────────────────────────────────────────────
// Reset — clear all edits and re-pull the latest Sleeper projections
// ─────────────────────────────────────────────────────────────────────────────
async function resetAll(){
  if(!confirm('Reset all projections and pull the latest projections from Sleeper?\n\nThis clears your current edits and imported/loaded data.')) return;
  // Stop any active draft-follow so the poll timer isn't orphaned after a full reset.
  if(typeof stopDraftFollow==='function' && typeof draftId!=='undefined' && draftId) stopDraftFollow();
  userProj={}; workingProj=userProj; importedSnapshot=null; dirtySinceImport=false;
  importedAnalystData=null; importedRawPayload=null;
  projBaseline=null;   // back to counting edits against the Sleeper seed
  playerNotes={};
  currentTeam=null; currentPhase='Passing'; undoStacks={};
  clearSession();   // wipe the saved session so the fresh pull isn't overwritten on next boot
  // Paint the cleared state now: if the Sleeper pull below fails (offline), the bar and dots
  // must not keep showing the edits that were just thrown away.
  renderSidebar();
  // refreshFromSleeper resets the working set to the fresh seed, re-renders, and toasts.
  await refreshFromSleeper();
  syncAppChrome();
}

// ─────────────────────────────────────────────────────────────────────────────
// Init
// ─────────────────────────────────────────────────────────────────────────────
seasonStatsCache['proj'] = SEED;
projSeed = SEED;
renderSeasonTabs();
renderSidebar();
syncAppChrome();

// ── Dev-mode tooling ──────────────────────────────────────────────────────
if(typeof TC_DEV_MODE!=='undefined' && TC_DEV_MODE){
  // Expose a live state inspector at window.tcDebug for console inspection.
  window.tcDebug = {
    get proj()    { return userProj; },
    get working() { return workingProj; },
    get season()  { return activeSeason; },
    get phase()   { return currentPhase; },
    get team()    { return currentTeam; },
    get format()  { return rankFormat; },
    get analysts(){ return importedAnalystData ? Object.keys(importedAnalystData) : null; },
    get draft()   { return { id: (typeof draftId!=='undefined'?draftId:null), picks: Object.keys(typeof draftedIds!=='undefined'?draftedIds:{}).length, active: !!(typeof draftTimer!=='undefined'&&draftTimer) }; },
    get cache()   { return { epoch: (typeof _buildPlayerCacheEpoch!=='undefined'?_buildPlayerCacheEpoch:null), hit: !!(typeof _buildPlayerCache!=='undefined'&&_buildPlayerCache.list) }; },
    buildPlayers(){ return (typeof buildPlayerList==='function') ? buildPlayerList() : null; },
    bust(){        if(typeof invalidateBuildPlayerCache==='function') invalidateBuildPlayerCache(); },
    dump(){
      console.group('[TC] App state');
      console.log('phase:', currentPhase, '| team:', currentTeam, '| season:', activeSeason, '| format:', rankFormat);
      console.log('teams with proj:', Object.keys(userProj).length);
      console.log('analysts:', importedAnalystData ? Object.keys(importedAnalystData).join(', ') : 'none');
      console.log('draft:', window.tcDebug.draft);
      console.log('cache:', window.tcDebug.cache);
      console.groupEnd();
    },
  };
  // Surface unhandled promise rejections and JS errors so they aren't silently swallowed.
  window.addEventListener('unhandledrejection', e=>{
    console.error('[TC] Unhandled rejection:', e.reason);
  });
  window.addEventListener('error', e=>{
    console.error('[TC] Uncaught error:', e.message, '@', e.filename+':'+e.lineno);
  });
  console.info('[TC] Dev mode active. window.tcDebug available — try tcDebug.dump()');
}

// If no seed is embedded (the default now — we pull live from Sleeper), fetch the
// current-season projections automatically on first load. A prebuilt triplecrown_seed.json
// (via the 📦 Seed button) or ↻ Sleeper can refresh/replace it at any time.
//
// On boot we ALSO try to fetch triplecrown_seed.json sitting next to the HTML, so the
// FantasyPros ECR (and any prebuilt projections/history) load automatically without a
// manual 📦 click. This works when the file is served over http(s); on a bare file://
// open the browser blocks it (CORS), and we silently fall back to the live Sleeper pull.
// Close the player card on Escape.
if(document&&document.addEventListener) document.addEventListener('keydown', e=>{ if(e.key==='Escape' && pcardOpen) closePlayerCard(); });
(async function boot(){
  // A baked/offline copy carries the NFL state it was built under — adopt it before anything
  // renders so phase/week gating works with zero network (the live probe still overrides).
  if(typeof SEED_STATE!=='undefined' && SEED_STATE && SEED_STATE.season && typeof _tcApplySeedState==='function') _tcApplySeedState(SEED_STATE);
  const hasEmbeddedProj = SEED && Object.keys(SEED).some(t=>SEED[t] && (SEED[t].QB.length||SEED[t].RB.length||SEED[t].WR.length||SEED[t].TE.length));
  const hasEmbeddedECR  = ECR && Object.keys(ECR).some(f=>ECR[f] && Object.keys(ECR[f]).length);
  // Paint an honest loading state BEFORE the first await. The template ships the "Select a
  // team to begin" empty state, which reads as "loaded and idle" — so a phone user used to
  // stare at a false ready state for the whole Sleeper round-trip, then watch it flip to
  // "Loading…" and back. (No season in the string: PROJ_SEASON may still be corrected by the
  // sync below, and a number that changes under you is worse than no number.)
  let _seedRawP = null;
  if(!hasEmbeddedProj){
    const _c = document.getElementById('content');
    if(_c) _c.innerHTML = `<div class="empty">
    <div class="empty-icon">${TC_ICON("signal","tc-ico-lg")}</div><div class="empty-title">Loading projections…</div>
    <div class="empty-body">Checking for a prebuilt seed, then pulling live from Sleeper if needed.</div></div>`;
    // Start the ~1.5MB seed download NOW rather than after the Sleeper season probe resolves.
    // These two requests hit different hosts and neither depends on the other's RESULT, so
    // running them back-to-back was costing a full extra round-trip on every cold load. The
    // seed is still APPLIED after the season sync below, so ordering semantics are unchanged.
    try{ _seedRawP = Promise.resolve(fetchSeedJson('seeds/triplecrown_seed.json')).catch(()=>null); }
    catch(e){ _seedRawP = null; }
  }
  if(!hasEmbeddedProj && typeof syncProjSeasonFromSleeper==='function'){
    await syncProjSeasonFromSleeper();
  }
  // If a seed was baked into this file (bake_seed.py), everything is already in memory —
  // no fetch, so it works when opened directly from a phone (file://) with no CORS issue.
  if(hasEmbeddedProj){
    const restored = restoreSession();
    _persistReady = true;
    renderSeasonTabs(); renderSidebar(); document.getElementById('content').innerHTML=emptyHTML();
    toast(`Loaded embedded seed${hasEmbeddedECR?' · ECR ready':''}${restored?' · session restored':''} ✓`,'ok');
    // Best-effort: pull the Sleeper player DB in the background so roster-membership checks
    // (used by "copy team to working set") have real data. Harmless if it fails (file://).
    loadSleeperPlayers(true).catch(()=>{});
    // Also refresh projection-season ADP live in the background so VONA/VOR stay current without a rebuild.
    backgroundRefreshADP();
    // In-season: pull current-season actuals + freeze the pace baseline (both no-op pre-season).
    if(typeof refreshLiveSeasonStats==='function') refreshLiveSeasonStats().catch(()=>{});
    if(typeof maybeFreezePaceBaseline==='function'){ try{ maybeFreezePaceBaseline(); }catch(e){} }
    if(typeof hasSeasonStarted==='function' && hasSeasonStarted() && typeof ensureInseasonSidecar==='function') ensureInseasonSidecar().catch(()=>{});
    // A baked copy opened over http can still learn the real week — self-gated, frozen-safe.
    if(typeof tcSeasonRecheck==='function'){ try{ tcSeasonRecheck(); }catch(e){} }
    return;
  }
  // Now that the season is settled, re-stamp the loading state with the real year.
  document.getElementById('content').innerHTML=`<div class="empty">
    <div class="empty-icon">${TC_ICON("signal","tc-ico-lg")}</div><div class="empty-title">Loading ${PROJ_SEASON} data…</div>
    <div class="empty-body">Checking for a prebuilt seed, then pulling live from Sleeper if needed.</div></div>`;
  // No embedded projections. Try a local seed file (works when served over http), which at
  // minimum gives us ECR; then fall back to a live Sleeper pull for projections.
  // The payload is usually already downloaded by now — hand it straight to tryAutoLoadSeed
  // rather than issuing a second request for it.
  const _seedRaw = _seedRawP ? await _seedRawP : null;
  // The prefetch already ran and came back empty — no seed is hosted here (or this is a bare
  // file:// open). Go straight to the live Sleeper pull instead of letting tryAutoLoadSeed
  // issue a second request for a file we already know isn't there.
  if(_seedRawP && !_seedRaw){ refreshFromSleeper(true); return; }
  tryAutoLoadSeed(_seedRaw).then(loaded=>{
    const hasProj = SEED && Object.keys(SEED).some(t=>SEED[t] && (SEED[t].QB.length||SEED[t].RB.length||SEED[t].WR.length||SEED[t].TE.length));
    if(hasProj){
      const restored = restoreSession();
      _persistReady = true;
      renderSeasonTabs(); renderSidebar(); document.getElementById('content').innerHTML=emptyHTML();
      if(restored) toast('Session restored ✓','ok');
      // Same background load so copy-to-working can verify current rosters.
      loadSleeperPlayers(true).catch(()=>{});
      backgroundRefreshADP();
      // In-season: pull current-season actuals + freeze the pace baseline (both no-op pre-season).
      if(typeof refreshLiveSeasonStats==='function') refreshLiveSeasonStats().catch(()=>{});
      if(typeof maybeFreezePaceBaseline==='function'){ try{ maybeFreezePaceBaseline(); }catch(e){} }
      // The live nflverse sidecar feeds the player-card charts and the Advanced tab in-season.
      if(typeof hasSeasonStarted==='function' && hasSeasonStarted() && typeof ensureInseasonSidecar==='function') ensureInseasonSidecar().catch(()=>{});
    }
    else refreshFromSleeper(true);   // ECR (if any) already adopted by tryAutoLoadSeed; restore happens there
  });
})();

// ── Resume / back-forward-cache recovery ─────────────────────────────────────
// Mobile browsers freeze a backgrounded tab in the bfcache and later restore the frozen DOM
// WITHOUT re-running any scripts. If the page was mid-load (or the OS discarded the renderer
// and repainted a stale frame) when you switched away, coming back showed a blank/half-loaded
// app until a manual refresh forced a fresh execution. boot() is a run-once IIFE, so nothing
// re-rendered on its own. These handlers fix that:
//   • pageshow{persisted:true} — a genuine bfcache restore. The JS heap is intact, so we just
//     re-render the current view rather than reload (instant, keeps your working edits).
//   • visibilitychange — when the tab becomes visible again, verify the content actually
//     rendered; if the seed is in memory but the DOM is empty (a discarded/stale paint),
//     re-render. Only if the seed itself is gone (heap was wiped) do we hard-reload.
(function installResumeRecovery(){
  if(typeof window==='undefined' || !window.addEventListener) return;

  // Is the app's data actually in memory right now?
  function seedInMemory(){
    try{ return typeof SEED!=='undefined' && SEED && Object.keys(SEED).some(t=>SEED[t] &&
      (SEED[t].QB.length||SEED[t].RB.length||SEED[t].WR.length||SEED[t].TE.length)); }
    catch(e){ return false; }
  }
  // Did the current view actually paint something?
  function contentRendered(){
    // childElementCount, not innerHTML: reading innerHTML serializes the entire subtree
    // (megabytes on the rankings board) and this runs on every visibilitychange/pageshow —
    // i.e. every app-switch and screen-off on a phone.
    const c=document.getElementById('content');
    return !!c && c.childElementCount>0;
  }
  // Re-render whatever view we're on, without touching data or re-fetching.
  function rerender(){
    try{
      if(typeof renderSeasonTabs==='function') renderSeasonTabs();
      if(typeof renderSidebar==='function') renderSidebar();
      if(typeof renderContent==='function') renderContent();
      else if(typeof emptyHTML==='function'){ const c=document.getElementById('content'); if(c) c.innerHTML=emptyHTML(); }
      if(typeof syncAppChrome==='function') syncAppChrome();
    }catch(e){ /* if a re-render throws, the reload path below is the safety net */ }
  }

  let _recoverAt=0;
  function recover(reason){
    // Debounce duplicate events (some browsers emit pageshow AND visibilitychange together) —
    // but NEVER swallow a recovery when the view is actually broken. A blank content div must
    // always be repaired, even if we just ran; only skip the redundant re-render of a view
    // that's already fine.
    const now=Date.now();
    const broken=!contentRendered();
    if(!broken && now-_recoverAt < 1200) return;
    _recoverAt=now;
    // A tab coming back after hours may have crossed Sleeper's Tue/Wed week flip — re-probe
    // the NFL state (self-gated to >6h old) so in-season data and gating advance with it.
    if(typeof tcSeasonRecheck==='function'){ try{ tcSeasonRecheck(); }catch(e){} }
    if(seedInMemory()){
      // Heap survived — cheapest correct fix is to re-render the frozen/blank view.
      if(broken || reason==='pageshow') rerender();
      // The dynasty-value table (DYNASTY_VALUES) is a SEPARATE global from SEED and may have
      // been dropped/emptied while SEED survived, which would show the analyzer with every
      // value, rank and persona at 0. If we're in the League view and the values look empty,
      // pull the seed again and re-render once it lands.
      try{
        if(typeof currentPhase!=='undefined' && currentPhase==='League'){
          const valsEmpty = !(typeof DYNASTY_VALUES!=='undefined' && DYNASTY_VALUES &&
                              DYNASTY_VALUES.players && Object.keys(DYNASTY_VALUES.players).length);
          if(valsEmpty && typeof tryAutoLoadSeed==='function'){
            tryAutoLoadSeed().then(()=>{
              if(typeof _laTierVals!=='undefined') _laTierVals=null;         // rebuild against fresh values
              if(typeof _laPosRankCache!=='undefined') _laPosRankCache=null;
              rerender();
            }).catch(()=>{});
          }
        }
      }catch(e){}
    } else if(_persistReady){
      // The renderer was discarded and the heap wiped, but we HAD booted once. A reload will
      // re-run boot() and restore the session from localStorage. This is the rare hard case.
      location.reload();
    }
    // If we never finished booting (!_persistReady, no seed), boot() is still in flight — leave it alone.
  }

  window.addEventListener('pageshow', e=>{ if(e.persisted) recover('pageshow'); });
  document.addEventListener('visibilitychange', ()=>{
    if(document.visibilityState==='visible') recover('visible');
  });
})();

// Attempt to fetch triplecrown_seed.json next to the page. Returns true if it loaded anything
// useful (at minimum ECR). Never throws — a file:// open or missing file just returns false.
// `prefetched` lets boot() hand over a payload it already downloaded in parallel with the
// Sleeper season probe. Omitted (every other caller) → fetch it here as before.
async function tryAutoLoadSeed(prefetched){
  try{
    // gz-first: build_seed ships a pre-compressed .json.gz twin — ~5x smaller on hosts that
    // don't compress, never worse (fetchSeedJson falls back to plain .json automatically).
    let raw = prefetched || await fetchSeedJson('seeds/triplecrown_seed.json');
    if(!raw) return false;
    const j = decodeAnySeed(raw);
    // decodeAnySeed rebuilds `history` and `nflverse` into new objects, so the compact
    // originals are dead the moment it returns — but `raw` kept the whole ~22MB tree
    // reachable for the rest of this function. Drop it so the GC can take it while we're
    // still doing the (allocation-heavy) assignments below.
    raw = null;
    // Adopt the seed's own season + NFL-state block: the projection label follows what the
    // data IS (a 2027 seed must not render under a 2026 label), and the state block gives a
    // phase/week fallback when the live Sleeper probe failed. Live truth still wins inside
    // _tcApplySeedState. Must happen before restoreSession() checks its season guard.
    if(j.season && typeof _tcApplyProjSeason==='function') _tcApplyProjSeason(j.season);
    if(j.state && typeof _tcApplySeedState==='function') _tcApplySeedState(j.state);
    let got=false;
    if(j.ecr){ ECR=j.ecr; got=true; }
    if(j.contracts){ CONTRACTS=j.contracts; got=true; }
    if(j.sharp){ SHARP=j.sharp; got=true; }
    if(j.sos){ SOS=j.sos; got=true; }
    if(j.market_model){ MARKET_MODEL=j.market_model; got=true; }
    if(j.team_names){ TEAM_NAMES=j.team_names; got=true; }
    if(j.coordinators){ COORDINATORS=j.coordinators; got=true; }
    if(j.coach_records){ COACH_RECORDS=j.coach_records; }
    if(j.hc_playcallers){ HC_PLAYCALLERS=j.hc_playcallers; got=true; }
    if(j.hc_history){ HC_HISTORY=j.hc_history; got=true; }
    if(j.additions){ ADDITIONS=j.additions; got=true; }
    if(j.sharp_season){ SHARP_SEASON=j.sharp_season; got=true; }
    if(j.sumer){ SUMER=j.sumer; SUMER_SEASONS=j.sumer_seasons||Object.keys(j.sumer); got=true; }
    if(j.ktc){ KTC=j.ktc; got=true; }   // KeepTradeCut dynasty player-page slugs (player-card links)
    if(j.dynasty_values){ DYNASTY_VALUES=j.dynasty_values; got=true;
      if(typeof laOnValuesLoaded==="function") laOnValuesLoaded(); }   // FP dynasty trade values → refresh analyzer
    if(j.nflverse){ NFLVERSE=j.nflverse; if(typeof resetNflverseLazy==='function') resetNflverseLazy(); got=true; }   // nflverse advanced metrics payload (heavy sections lazy-load)
    if(j.cfb){ CFB=j.cfb; if(typeof resetCfbLazy==='function') resetCfbLazy(); got=true; }   // college rookie profiles (game logs lazy-load)
    // Only adopt prebuilt projections/history if present and non-trivial.
    if(j.seed && Object.keys(j.seed).length){
      SEED=j.seed; projSeed=SEED; seasonStatsCache={proj:SEED}; rosterMergedTeams.clear();
      HISTORY=j.history||{}; HISTORY_SEASONS=j.history_seasons||[];
      workingProj={}; userProj=workingProj; activeSeason='proj';
      got=true;
    }
    if(got){
      const n=j.seed?Object.values(j.seed).reduce((s,t)=>s+(t.QB||[]).length+(t.RB||[]).length+(t.WR||[]).length+(t.TE||[]).length,0):0;
      const ecrN=j.ecr?Object.keys(ecrTableFor(rankFormat)||{}).length:0;
      toast(`Auto-loaded seed${ecrN?` · ${ecrN} ECR ranks`:''}${n?` · ${n} players`:''} ✓`,'ok');
      if(typeof prewarmRankingsFromSeed==='function') prewarmRankingsFromSeed();
    }
    return got;
  }catch(e){
    // CORS (file://) or network error — expected when opened directly; fall back silently.
    return false;
  }
}


// ─────────────────────────────────────────────────────────────────────────────
// Supabase Auth + Cloud Projections Manager
// ─────────────────────────────────────────────────────────────────────────────
//
// SETUP (one-time, ~5 minutes):
//
// 1. Go to https://supabase.com → New project (free tier, no credit card)
// 2. Settings → API → copy "Project URL" and "anon public" key into the two
//    constants below.
// 3. For Google sign-in: Authentication → Providers → Google → enable it,
//    paste your Google OAuth client ID + secret (from console.cloud.google.com).
// 4. Run this SQL once in the Supabase SQL Editor:
//
//   create table if not exists tc_projections (
//     id          uuid        primary key default gen_random_uuid(),
//     user_id     uuid        references auth.users not null,
//     name        text        not null default 'My Projections',
//     season      text,
//     sort_order  int         default 0,
//     data        jsonb       not null,
//     created_at  timestamptz default now(),
//     updated_at  timestamptz default now()
//   );
//   alter table tc_projections enable row level security;
//   create policy "users own their projections"
//     on tc_projections for all
//     using  (auth.uid() = user_id)
//     with check (auth.uid() = user_id);
//
// ─────────────────────────────────────────────────────────────────────────────

const TC_SUPABASE_URL      = 'https://agnbcpczmrsoszdjxrqr.supabase.co';  // 'https://xxxxxxxxxx.supabase.co'
const TC_SUPABASE_ANON_KEY = 'sb_publishable_sF7QFEaRJx_USKUqmIZQcQ_y1QAnUKi';  // 'eyJ...'

// ── Internal state ────────────────────────────────────────────────────────────
let _tcClient = null;
let _tcUser   = null;
let _tcMgrProjs = [];   // cached projection list for manager

// ── Initialise Supabase client (lazily) ──────────────────────────────────────
// The SDK is no longer a blocking script tag in the document head (see 04-script-loader.js), so the
// client is built on demand. tcEnsureSupabase() is idempotent and safe to call from any
// entry point; it resolves true once _tcClient is usable.
let _tcInitPromise = null;
function tcEnsureSupabase(){
  if(_tcClient) return Promise.resolve(true);
  if(_tcInitPromise) return _tcInitPromise;
  if(typeof window === 'undefined') return Promise.resolve(false);
  if(!TC_SUPABASE_URL || !TC_SUPABASE_ANON_KEY) return Promise.resolve(false);  // not configured
  _tcInitPromise = tcEnsureSupabaseSdk().then(ok=>{
    if(!ok){
      console.warn('[TC] Supabase SDK could not be loaded — cloud features disabled');
      _tcInitPromise = null;   // allow a retry on the next attempt
      return false;
    }
    try{
      _tcClient = window.supabase.createClient(TC_SUPABASE_URL, TC_SUPABASE_ANON_KEY);
      // Restore an existing session from localStorage.
      _tcClient.auth.getSession().then(({data:{session}})=>{
        _tcUser = session ? session.user : null;
        syncAuthChrome();
      }).catch(e=>console.warn('[TC] getSession error:', e));
      // Keep state in sync whenever auth changes (sign-in, sign-out, token refresh)
      _tcClient.auth.onAuthStateChange((_event, session)=>{
        _tcUser = session ? session.user : null;
        syncAuthChrome();
      });
      return true;
    }catch(e){
      console.warn('[TC] Supabase init error:', e);
      _tcInitPromise = null;
      return false;
    }
  });
  return _tcInitPromise;
}

// A signed-in user must still come back to a signed-in app without touching anything,
// so if supabase-js left an auth token in localStorage on a previous visit we bring the
// SDK up in the background once boot is out of the way. A signed-OUT visitor — the
// common case, and every offline/baked copy — never requests it at all.
function _tcHasStoredSession(){
  try{
    if(typeof localStorage==='undefined' || !localStorage) return false;
    for(let i=0;i<localStorage.length;i++){
      const k = localStorage.key(i);
      // supabase-js v2 stores `sb-<project-ref>-auth-token`.
      if(k && /^sb-.*-auth-token$/.test(k)) return true;
    }
  }catch(e){}
  return false;
}
// An OAuth redirect (Google sign-in) lands back with the session in the URL fragment, NOT in
// localStorage — only the SDK's detectSessionInUrl can consume it. Before this check, that
// first landing looked signed-out (no sb- key yet), the fragment was never consumed, and the
// user had to sign in a second time before the menu showed their name.
function _tcHasAuthRedirect(){
  try{
    return /access_token=|refresh_token=|type=recovery|error_description=|[?&#]code=/.test(
      (window.location.hash||'') + (window.location.search||''));
  }catch(e){ return false; }
}
(function _tcRestoreIfSignedIn(){
  if(typeof window==='undefined') return;
  if(_tcHasAuthRedirect()){ tcEnsureSupabase().catch(()=>{}); return; }   // consume it NOW
  if(!_tcHasStoredSession()) return;
  const go = ()=>{ tcEnsureSupabase().catch(()=>{}); };
  if(typeof requestIdleCallback==='function') requestIdleCallback(go, {timeout:3000});
  else setTimeout(go, 1200);
})();

// Sync chrome once immediately so Save/Manager buttons appear as soon as the
// script runs (before the async getSession() resolves). This runs AFTER syncAppChrome
// in 85-import-export.js since 86 comes after 85 in build order.
syncAuthChrome();

// ── Chrome sync — called by syncAppChrome (85) AND by auth state changes ──────
function syncAuthChrome(){
  // syncAppChrome() in 85-import-export.js may call this during init, BEFORE this file's
  // top-level `const` declarations execute. `const` is in the temporal dead zone until then,
  // so reading TC_SUPABASE_URL would throw a ReferenceError. Guard with try/catch and bail
  // out early — 86's own trailing syncAuthChrome() call re-runs this once the consts exist.
  let configured = false;
  try{
    configured = !!(TC_SUPABASE_URL && TC_SUPABASE_ANON_KEY);
  }catch(e){ return; }

  const signedIn = !!_tcUser;

  // Auth button: use innerHTML so the TC_ICON SVG renders alongside the label
  const authBtn = document.getElementById('menuAuthBtn');
  if(authBtn){
    const iconHtml = (typeof TC_ICON==='function') ? TC_ICON('user') : '';
    const labelTxt = signedIn
      ? (_tcUser.email||'').split('@')[0]
      : 'Sign In';
    authBtn.innerHTML = `${iconHtml} ${escHtml(labelTxt)}`;
    authBtn.title = signedIn ? (_tcUser.email||'') : 'Sign in to save projections';
  }

  // Save + Manager only visible when Supabase is configured
  ['menuSaveBtn','menuManagerBtn'].forEach(id=>{
    const el = document.getElementById(id);
    if(el) el.style.display = configured ? '' : 'none';
  });
}

